import type { SshKey } from '@seti/shared'
import { Input } from '@/components/ui/input'
import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select'
import { Switch } from '@/components/ui/switch'
import { NEW_KEY, type KeyChoice } from './key-choice'
import { PrivateKeyField } from './key-fields'

/**
 * Picks the one key a host logs in with, or makes a new one inline: generated by Seti or pasted.
 * `carried` marks a host that came over from older settings without a key.
 */
export function KeyPicker({
  keys,
  choice,
  carried = false,
  onChange,
}: {
  keys: readonly SshKey[]
  choice: KeyChoice
  carried?: boolean
  onChange: (next: KeyChoice) => void
}) {
  const patch = (next: Partial<KeyChoice>) => {
    onChange({ ...choice, ...next })
  }
  return (
    <div className="flex w-full min-w-0 flex-col gap-2">
      <NativeSelect
        aria-label="SSH key"
        aria-invalid={carried && choice.keyId === ''}
        className="w-full"
        value={choice.keyId}
        onChange={(event) => {
          patch({ keyId: event.target.value })
        }}
      >
        {choice.keyId === '' && (
          <NativeSelectOption value="">{carried ? 'No key: choose one' : 'Choose a key'}</NativeSelectOption>
        )}
        {keys.map((key) => (
          <NativeSelectOption key={key.id} value={key.id}>
            {key.name}
          </NativeSelectOption>
        ))}
        <NativeSelectOption value={NEW_KEY}>New key</NativeSelectOption>
      </NativeSelect>
      {choice.keyId === NEW_KEY && (
        <>
          <Input
            aria-label="New key name"
            autoComplete="off"
            placeholder="Key name"
            value={choice.name}
            onChange={(event) => {
              patch({ name: event.target.value })
            }}
          />
          <label className="flex items-center gap-2 text-xs text-muted-foreground">
            <Switch
              aria-label="Paste a private key"
              checked={choice.paste}
              onCheckedChange={(paste) => {
                patch({ paste })
              }}
            />
            {choice.paste ? 'Paste a private key Seti seals' : 'Seti generates an ed25519 key'}
          </label>
          {choice.paste && (
            <PrivateKeyField
              value={choice.privateKey}
              onChange={(privateKey) => {
                patch({ privateKey })
              }}
            />
          )}
        </>
      )}
    </div>
  )
}
